def parse(text):
    if type(text)is not str:return dict(status='UNSUPPORTED_LITERAL_TYPE',interpretations=[])
    found={}
    for spelling,root in ROOT_SPELLINGS.items():
        if not text.startswith(spelling):continue
        tail=text[len(spelling):];options=[(tail,None)]
        if '/' in tail:
            quality,bass=tail.rsplit('/',1)
            if bass in ROOT_SPELLINGS:options.append((quality,ROOT_SPELLINGS[bass]))
        for quality,bass in options:
            for kind in QUALITY_ALIASES.get(quality,[]):
                value=dict(root_pc=root,kind=kind,explicit_bass_pc=bass)
                found[root,kind,bass]=value
    values=sorted(found.values(),key=lambda v:(v['root_pc'],v['kind'],-1 if v['explicit_bass_pc'] is None else v['explicit_bass_pc']))
    return dict(status='UNIQUE_LIBRARY_SYMBOL' if len(values)==1 else 'AMBIGUOUS_SYMBOL' if values else 'UNSUPPORTED_SYMBOL',interpretations=values)
